from typing import Dict, Any

def get_mat_the_bang_gia_masterpiece_story(title: str = '') -> Dict[str, Any]:
    story_title = title if title else "Trọng Sinh Về 30 Ngày Trước Tận Thế Băng Giá Âm 60 Độ: Pháo Đài Nhiệt Ngầm 100 Tỷ"
    part1_full = "Cột thủy ngân của nhiệt kế gắn ngoài ban công tầng mười tám tụt thẳng xuống mức âm năm mươi hai độ C, làm lớp kính thường của các căn hộ đối diện nứt toác từng vệt dài. Nhiệt kế thủy ngân ngoài ban công vừa tụt xuống âm năm mươi hai độ C, tiếng kính cường lực tầng mười tám đã nứt toác từng vệt dài rôm rốp như tiếng bẻ gãy bánh đa giòn.\n\nTôi đứng tựa lưng vào vách tường sưởi hồng ngoại bằng đá hoa cương, hai tay đút túi áo khoác lông vũ chịu nhiệt âm bảy mươi độ. Trên bảng điều khiển điện tử ở góc phòng, dòng điện ba pha từ tổ hợp máy phát điện turbine hơi nước ngầm đang báo công suất một trăm phần trăm, tỏa ra hơi ấm hai mươi tư độ êm dịu khắp không gian căn hộ.\n\nCả tòa chung cư hai mươi tư tầng giữa trung tâm thành phố lúc này chìm trong bóng tối câm lặng và nỗi sợ hãi tột cùng. Trạm biến áp khu vực vừa nổ tung trong cơn lốc bão tuyết cách đây hai mươi phút, cắt đứt hoàn toàn nguồn điện lưới và tê liệt hệ thống lò sưởi trung tâm của bốn nghìn hộ dân. Bên ngoài hành lang, tiếng gió rít qua khe cửa nghe như tiếng gầm rú của bầy dã thú đói mồi.\n\nKiếp trước, đúng vào đêm tuyết rơi kinh hoàng này, người anh rể họ Vương Cương cùng ả chị gái độc đoán đã dùng lời ngon ngọt lừa tôi mở chốt cửa căn hộ. Bọn họ cướp đi chiếc máy phát điện mini duy nhất, ném tôi ra ngoài hành lang buốt giá giữa đêm tuyết âm bốn mươi độ C cho đến chết cóng trong sự tuyệt vọng cùng cực.\n\nTrọng sinh về ba mươi ngày trước thảm họa, tôi bán đứt căn nhà mặt phố và rút sạch một trăm tỷ tiền tiết kiệm trong ngân hàng. Tôi biến căn penthouse tầng mười tám này thành một pháo đài nhiệt ngầm kiên cố bất khả xâm phạm: kính cách nhiệt ba lớp chân không titan chịu lực cấp mười sáu, vách tường ốp mút cách nhiệt chống đóng băng dày dặn, hệ thống lưu trữ năng lượng pin mặt trời graphene và kho thực phẩm khô tự sôi đủ dùng thoải mái trong mười năm.\n\nCăn hộ penthouse tầng mười tám này được tôi cải tạo theo tiêu chuẩn của một trạm nghiên cứu vùng cực Bắc. Toàn bộ các bức tường tiếp giáp ngoài trời đều được gia cố thêm một lớp bông thủy tinh cách nhiệt mật độ cao và ốp thêm tấm thạch cao chống cháy. Toàn bộ hệ thống cửa sổ kính thông thường đã bị tôi thay thế bằng kính cường lực ba lớp có bơm khí trơ argon ở giữa, giúp ngăn chặn hoàn toàn hiện tượng thất thoát nhiệt lượng ra môi trường băng giá bên ngoài.\n\nỞ góc phòng ăn, hai bể chứa nước sinh hoạt dung tích ba ngàn lít được tôi bọc lớp xốp giữ nhiệt và trang bị thanh sưởi nhiệt chìm điều khiển tự động, giữ cho nước luôn ở mức nhiệt độ mười độ C để không bao giờ bị đóng băng. Tôi còn dự trữ ba mươi bình gas công nghiệp loại bốn mươi tám ký được xếp ngay ngắn trong khu vực thông gió an toàn, kèm theo năm tấn củi nén mùn cưa và ba tổ máy sưởi dầu cao cấp. Trong khi cả thành phố đang run rẩy co ro trong bóng tối buốt giá, căn nhà của tôi vẫn ấm áp như một mùa xuân thu nhỏ.\n\nTừng bao gạo thơm, từng thùng dầu ăn, thịt hun khói, cá hộp và lương khô năng lượng cao được tôi bí mật vận chuyển lên tầng thượng lúc nửa đêm. Tôi còn lắp đặt hệ thống máy bay không người lái trinh sát tầm nhiệt để giám sát an ninh toàn bộ tòa nhà từ trên cao. Khi nhiệt độ bắt đầu hạ thấp, nhóm chat cư dân của tòa chung cư bắt đầu hỗn loạn với hàng trăm tin nhắn cầu cứu, than khóc vì thiếu chăn ấm và cạn kiệt thức ăn. \n\nTách! Tiếng chuông cửa cơ học kết nối camera hồng ngoại bỗng reo lên một tiếng khô khốc giữa đêm đông.\n\nMàn hình hiển thị gương mặt tím tái của Vương Cương và ả chị họ. Hai người họ trùm chăn bông rách rưới bám đầy tuyết trắng, răng đánh vào nhau lập cập phát ra tiếng lách cách:\n'Tiểu Minh ơi! Mở cửa cho anh chị vào với! Lò sưởi dưới nhà tắt ngấm rồi, nhiệt độ trong phòng đang âm hai mươi độ, cháu gái em đang sắp chết cóng rồi! Cho anh chị tá túc vài hôm, anh chị sẽ đền ơn em sau!'.\n\nTôi nhìn chiếc camera quét tầm nhiệt 3D gắn trước cửa. Thân nhiệt của hai kẻ ngoài cửa hiển thị màu xanh lam nhạt báo hiệu hạ thân nhiệt, nhưng sau lưng Vương Cương, một chiếc rìu phá cửa bằng thép bọc vải đen đang được gã giấu kín dưới lớp chăn bông, chỉ chực chờ cánh cửa hé mở là xông vào chém giết chiếm đoạt pháo đài.\n\nTôi bật loa đàm thoại ngoài cửa, giọng bình thản không chút hơi ấm:\n'Anh rể họ, cửa này là thép vonfram đúc nguyên khối nặng ba tấn, khóa mã vân tay kết hợp nhận diện võng mạc. Muốn ấm thì mời anh chị xuống sảnh tầng một gom lốp xe cao su lại mà đốt sưởi ấm, đừng làm phiền giấc ngủ của tôi!'.\n\nNhóm chat cư dân của tòa nhà chung cư hai mươi tư tầng lúc này ngập tràn những tin nhắn hỗn loạn và hoảng loạn. Ban quản trị tòa nhà thông báo hệ thống cáp treo thang máy đã bị đông cứng hoàn toàn do băng giá ngưng tụ, việc di chuyển lên xuống các tầng cao chỉ có thể thực hiện bằng cầu thang bộ thoát hiểm dốc đứng bám đầy sương muối trơn trượt. Các gia đình có con nhỏ bắt đầu đốt sách vở, quần áo cũ và cả bàn ghế gỗ ngay trong phòng khách để sưởi ấm, khiến khói đen bốc lên nghi ngút làm còi báo cháy kêu inh ỏi khắp nơi.\n\nTôi mở tủ điện trung tâm kiểm tra lại thông số của dàn pin lưu trữ năng lượng mặt trời công nghệ mới. Nhờ lớp kính titan phản xạ nhiệt và hệ thống sấy kính tự động bằng điện trở mỏng, bề mặt các tấm pin lắp trên mái căn hộ hoàn toàn không bị tuyết phủ đóng băng, vẫn tiếp tục hấp thụ bức xạ ánh sáng khuếch tán yếu ớt qua màn mây mù để sạc điện cho hệ thống lưu trữ. Mọi rủi ro kỹ thuật đều đã được tôi tính toán phương án dự phòng kép. Trong cuộc chiến sinh tồn giữa thảm họa thiên nhiên, sự tỉ mỉ và chuẩn bị khoa học chính là ranh giới duy nhất phân định giữa sự sống và cái chết.\n\nTôi cầm bình xịt bọt xốp cách nhiệt polyurethane đi một vòng quanh căn hộ kiểm tra lại toàn bộ các khe hở tiếp giáp giữa khung cửa nhôm và vách tường bê tông. Từng milimét kẽ hở đều được tôi bơm đầy bọt xốp nở kín mít, ngăn chặn triệt để hiện tượng cầu nhiệt gây ngưng tụ sương giá. Trên các ô cửa kính ban công, tôi buông thêm hai lớp rèm nhung dày dặn có tráng lớp màng nhôm phản xạ bức xạ nhiệt, giữ lại tối đa hơi ấm hai mươi tư độ C bên trong phòng khách.\n\nTại phòng kỹ thuật phụ, tổ hợp máy phát điện turbine hơi nước ngầm công suất năm mươi kilowatt đang vận hành cực kỳ êm ái nhờ hệ thống tiêu âm ba tầng. Nguồn nhiên liệu biomass từ mùn cưa ép được nạp tự động qua băng tải trục vít, bảo đảm nguồn cung cấp nhiệt và điện liên tục mà không cần can thiệp thủ công. Tôi kiểm tra đồng hồ áp suất và van xả an toàn, mọi thông số đều nằm trong dải an toàn tuyệt đối. Căn pháo đài nhiệt ngầm này chính là kết tinh của trí tuệ, sự kiên định và nguồn lực chuẩn bị chu đáo nhất."
    part2_full = "Tiếng rìu sắt bổ mạnh vào ổ khóa vân tay ngoài cửa căn hộ vang lên chát chúa giữa hành lang đóng băng, ngay lập tức kích hoạt hệ thống còi báo động chống đột nhập tự động. Lưỡi rìu thép vừa giáng xuống mép khóa điện tử một tiếng 'Coong!' vang dội khắp hành lang, tia lửa điện xanh loét đã tóe ra kèm tiếng rên rỉ thất vọng của Vương Cương.\n\nLớp thép hợp kim dày mười phân phủ lớp cách nhiệt chân không không hề móp méo dù chỉ một milimét. Toàn bộ chấn động cơ học từ cú rìu dội ngược lại cánh tay gã đàn ông, khiến cán rìu rung lên bần bật, khớp cổ tay gã tê dại vì phản lực quá lớn.\n\nẢ chị họ thấy bẫy phá cửa bất thành, lập tức quỳ sụp xuống sàn gạch bám đầy băng trắng buốt, gào thét khản đặc qua micro cửa:\n'Tiểu Minh! Mày là đồ máu lạnh vô nhân tính, mất hết lương tâm rồi! Trong nhà mày ấm hai mươi lăm độ, có đèn điện sáng trưng, mà mày nỡ trơ mắt nhìn người nhà chết cóng ngay trước cửa sao? Mày mở cửa ra chia cho tao một chiếc lò sưởi dầu và vài cân gạo thôi, tao hứa sẽ không động vào hạt gạo nào khác của mày!'.\n\nTôi ngồi trên ghế nệm bọc da, ngón tay nhấp nhẹ trên chiếc máy tính bảng kết nối trực tiếp hệ thống an ninh đa tầng ngoài hành lang. \n\nQua camera độ phân giải 4K hồng ngoại góc rộng, tôi thấy rõ ba gã hàng xóm to con ở căn hộ đối diện đang kéo theo hai chiếc xà beng và bình gas du lịch tiếp cận mép cửa thoát hiểm. Bọn họ cấu kết với Vương Cương, định dùng lửa hơ nóng ổ khóa rồi dùng đòn bẩy cạy tung bản lề cánh cửa thép. \n\nNhìn qua ô kính quan sát chống đạn, cảnh tượng bên ngoài hành lang tầng mười tám hệt như một bức tranh hoang tàn thời tiền sử. Hơi thở của đám người phả ra lập tức ngưng tụ thành những đám sương trắng đục rồi đóng băng bám trắng xóa lên lông mi và râu ria của họ. Vương Cương ôm cánh tay trật khớp rên rỉ, trong mắt chỉ còn lại sự khiếp sợ tột cùng. Hắn ta từng nghĩ rằng với chiếc rìu sắt và mấy tên côn đồ hung tợn, hắn có thể dễ dàng đoạt lấy căn nhà ấm áp của tôi như kiếp trước. Nhưng hắn đã quên mất rằng, một khi con người đã trải qua cái chết, họ sẽ không bao giờ mắc lại sai lầm ngây thơ lần thứ hai.\n\nTôi khẽ nhếch mép, giọng phát qua loa ngoài lạnh lùng như băng vĩnh cửu:\n'Các vị hàng xóm thân mến! Có phải các vị đang muốn dùng lửa gas để nướng chảy then cài này không? Cánh cửa này được gia cố bằng lõi thép chống cháy hai tiếng và có chốt ngầm đa điểm ăn sâu vào khung bê tông cốt thép. Các vị có đập đến gãy tay thì chỉ làm tốn thêm chút calo ít ỏi còn lại trong cơ thể mà thôi!'.\n\nTôi nhấn nút kích hoạt hệ thống phun nước muối áp lực cao được làm nóng sẵn ở nhiệt độ tám mươi độ C từ hai đầu vòi ẩn trên mép cửa. \n\nXoẹt! Một làn nước muối nóng đậm đặc bắn thẳng xuống mặt sàn hành lang trước cửa căn hộ! Khi gặp nền nhiệt âm ba mươi độ C ngoài hành lang, lớp nước muối lập tức tạo thành một lớp băng bóng nhẫy, trơn trượt như sân trượt băng nghệ thuật!\n\nBa gã đàn ông đang vung xà beng lập tức mất thăng bằng, ngã nhào ngửa đập lưng xuống sàn đá hoa cương trơn tuột! Tiếng xương khớp va chạm lộp cộp, tiếng chửi rủa và tiếng la hét đau đớn vang vọng khắp tầng mười tám. Bọn chúng không thể nào gượng đứng dậy nổi vì mặt sàn trơn nhẫy không có điểm tựa, chỉ có thể vừa chửi rủa vừa bò lết tháo lui về phía cầu thang bộ trong nhục nhã!\n\nTôi cầm cốc trà gừng ấm nóng trên tay, nhìn đám người lảo đảo dìu nhau rời khỏi cửa căn hộ. Trong thế giới cực hàn này, lòng trắc ẩn mù quáng chính là liều thuốc độc tự sát nhanh nhất. Kẻ chỉ biết dùng vũ lực để cướp bóc người khác sẽ mãi mãi không hiểu được rằng, sự chuẩn bị chu đáo và lao động chân chính mới là tấm khiên vững chắc nhất bảo vệ sinh mệnh của mỗi con người.\n\nTôi mỉm cười tắt hệ thống phun, đứng bên lò sưởi thưởng thức bữa tối với món lẩu bò cay nóng sốt. Sự kiên cố và chuẩn bị chu đáo chính là vũ khí mạnh nhất để sinh tồn giữa thời khắc nhân tính bị thử thách nghiệt ngã nhất!\n\nNhìn đám người co ro tháo chạy, tôi mở máy bộ đàm quét các dải tần số khẩn cấp của chính quyền thành phố. Tín hiệu vô tuyến chập chờn cho biết trạm cứu nạn trung tâm đang nỗ lực điều động các đoàn xe lội tuyết hạng nặng và công binh đến giải cứu các khu dân cư bị cô lập. Tuy nhiên, do lớp băng tuyết trên các tuyến đường quốc lộ quá dày, các lực lượng cứu hộ dự kiến phải mất từ mười đến mười lăm ngày mới có thể tiếp cận được khu vực nội đô.\n\nTôi kiểm tra lại kho dược phẩm sinh tồn được cất giữ trong tủ tiệt trùng chân không. Hàng trăm vỉ thuốc hạ sốt, kháng sinh, thuốc nhỏ mắt chống bỏng tuyết và các tuýp mỡ bôi chống nứt nẻ da do lạnh được tôi xếp gọn gàng theo từng danh mục. Tôi biết rằng sau đợt bão tuyết này, dịch bệnh đường hô hấp và các chấn thương do hạ thân nhiệt sẽ bùng phát dữ dội. Những thứ thuốc men thông thường này sẽ trở thành phao cứu sinh vô giá để giúp đỡ những người xứng đáng khi trật tự xã hội dần được tái thiết lập.\n\nTiếng còi hú và loa phát thanh nội bộ của ban quản trị tòa nhà bất ngờ vang lên dồn dập từ phía hành lang. Trưởng ban quản trị – một người đàn ông trung niên vốn nổi tiếng hách dịch – dùng loa cầm tay quát tháo yêu cầu tôi mở cửa: 'Căn hộ 1801! Ban quản trị và tập thể cư dân đã họp và quyết định trưng dụng nguồn điện và lương thực dự trữ của anh để chia sẻ cho các hộ gia đình khó khăn! Anh phải có trách nhiệm với cộng đồng trong tình huống khẩn cấp, nếu không chúng tôi sẽ cưỡng chế phá cửa!'.\n\nTôi bật loa đối thoại ngoài cửa, giọng nói rành rọt từng điều luật: 'Ông Trần, theo quy định của Bộ luật Dân sự và Luật Tình trạng khẩn cấp, chỉ có Ủy ban Nhân dân và cơ quan quân sự có thẩm quyền mới có quyền trưng dụng tài sản của công dân và phải có biên bản bồi thường bằng văn bản. Ban quản trị không có bất kỳ tư cách pháp lý nào để xâm phạm nơi ở hợp pháp của tôi! Nếu các người dám manh động dùng vũ lực phá hoại tài sản, hệ thống camera an ninh truyền thẳng lên máy chủ đám mây của tôi sẽ ghi lại đầy đủ chứng cứ để đưa toàn bộ các người ra trước tòa án xét xử về tội cướp tài sản có tổ chức!'. Lời lẽ đanh thép và am hiểu pháp luật của tôi khiến đám người bên ngoài câm nín, đưa mắt nhìn nhau rồi lấm lét tháo lui không dám manh động thêm nửa bước."
    part3_full = "Sau mười lăm ngày bão tuyết cực hàn vùi lấp toàn bộ khu đô thị dưới lớp băng dày bốn mét, tiếng động cơ xe bánh xích cứu hộ quân sự cuối cùng cũng vang lên từ phía đại lộ. Tiếng còi hú của đoàn xe bọc thép phá băng quân sự vừa vang lên dồn dập từ phía đại lộ dưới sảnh, Vương Cương đã nằm co quắp trên bậc thềm hành lang với hai bàn tay tím bầm vì giá rét.\n\nBão tuyết ngoài trời vẫn gầm rú với sức gió giật cấp mười ba, nhiệt độ rớt thẳng xuống âm sáu mươi độ C. Toàn bộ thành phố đã biến thành một kỷ băng hà trắng xóa hoang tàn, lớp băng tuyết dày tới mét rưỡi chôn vùi hàng nghìn chiếc ô tô chết máy nằm la liệt trên các ngả đường.\n\nVương Cương run rẩy ngước nhìn bóng người cao ráo đĩnh đạc của tôi qua ô kính chịu lực ba lớp. Gã van lạy trong hơi thở đứt quãng yếu ớt:\n'Tha cho anh... Minh ơi... Cho anh xin một ngụm nước ấm thôi... Anh biết tội rồi... Kiếp trước hay kiếp này anh cũng sai rồi... Đừng bỏ mặc anh chết trong băng giá...'.\n\nTôi bước đến bên cửa kính, nâng tách sô cô la nóng hổi bốc khói thơm lừng, giọng nói rành rọt đanh thép qua màn hình đàm thoại ngoài:\n'Vương Cương, chiếc máy phát điện ngày xưa anh cướp của tôi, anh có nhớ anh đã nói gì không? Anh bảo kẻ yếu đuối trong ngày tận thế thì xứng đáng bị vứt ra ngoài giá rét cho đông cứng. Giờ thì anh hãy tự mình trải nghiệm trọn vẹn những lời anh từng dạy đi!'.\n\nRầm! Cửa sắt cầu thang bộ tầng mười tám bị đẩy tung bởi lực lượng cứu hộ chuyên trách. \n\nMột đội công binh mặc quân phục chống rét chuyên dụng mang theo đèn pha công suất lớn và cáng cứu thương ập vào hành lang.\n\nViên sĩ quan chỉ huy nhìn Vương Cương và đám người nằm co ro vì rét, rồi bước đến trước cửa căn hộ của tôi, đưa tay nghiêm cẩn chào theo điều lệnh:\n'Đồng chí Lâm Minh! Chúng tôi nhận được tín hiệu định vị vô tuyến và bản đồ trạm sạc điện mặt trời dự phòng do đồng chí phát lên tần số cứu hộ ba ngày trước! Căn cứ cứu trợ tiền phương số một đang rất cần chia sẻ nguồn điện turbine ngầm để cấp ấm cho trung tâm y tế dã chiến cách đây một cây số. Đồng chí có thể phối hợp cùng quân đội hỗ trợ cứu dân không?'.\n\nKhi đoàn xe thiết giáp cứu hộ quân sự bắt đầu dọn dẹp các tuyến đường huyết mạch, ánh mặt trời đầu tiên sau chuỗi ngày bão tuyết mịt mù cuối cùng cũng chiếu rọi lên tầng mười tám. Từng tảng băng dày trên lan can ban công bắt đầu nhỏ những giọt nước tí tách xuống đất. Tôi cùng các chiến sĩ công binh triển khai đường dây cáp điện dự phòng từ trạm phát điện của mình xuống trung tâm y tế dã chiến dưới sảnh chung cư, thắp sáng lại niềm hy vọng sống cho hàng trăm người dân vô tội.\n\nTôi mỉm cười gật đầu, tra chìa khóa cơ xoay mở cánh cửa thép ba lớp:\n'Tôi đã dự trữ sẵn dây cáp tải điện chịu hàn và hai trăm khối than nén sinh học. Toàn bộ thiết bị dự phòng đều sẵn sàng để bàn giao cho lực lượng cứu hộ phục vụ nhân dân! Mời các đồng chí vào trong uống một tách trà nóng sưởi ấm!'.\n\nSự kiên định và chuẩn bị đúng đắn đã giúp tôi không chỉ bảo toàn được tính mạng của chính mình mà còn trở thành điểm tựa vững chãi cho cộng đồng trong thời khắc gian nan nhất. Cánh cửa pháo đài mở ra, hơi ấm từ căn phòng ùa ra làm tan chảy những giọt băng vương trên vai áo những người lính cứu nạn. Công lý và sự kiên cường đã chiến thắng sự ích kỷ, mở ra một bình minh ấm áp sau chuỗi ngày tăm tối nhất của kỷ băng hà!\n\nBa ngày sau khi đoàn cứu hộ tiếp quản tầng sảnh tòa nhà, một trạm phân phát lương thực dã chiến và sưởi ấm công cộng đã được thiết lập thành công nhờ nguồn điện turbine hơi nước ổn định từ căn hộ của tôi. Hàng trăm người dân, đặc biệt là người già và trẻ nhỏ trong khu đô thị, đã được cứu sống khỏi lưỡi hái tử thần của cái lạnh âm sáu mươi độ C. Những giọt nước mắt xúc động và những cái nắm tay cảm ơn chân thành của bà con lối xóm đã sưởi ấm tâm hồn tôi hơn bất kỳ lò sưởi nào.\n\nỦy ban cứu trợ thảm họa quốc gia đã trao tặng tôi bằng khen danh dự và huy hiệu anh hùng dân sự vì những đóng góp xuất sắc trong công tác bảo vệ tính mạng nhân dân. Tôi đứng trên ban công tầng mười tám, nhìn ngắm thành phố thân yêu đang dần hồi sinh dưới ánh nắng xuân ấm áp rực rỡ. Cuộc đời này, khi ta biết sống kiên cường, chuẩn bị chu đáo và giữ vững lòng nhân ái đúng nơi đúng chỗ, bão giông nào rồi cũng sẽ lùi xa, nhường chỗ cho bình minh rạng ngời và tươi sáng nhất!\n\nSau khi bàn giao hệ thống điện dự phòng cho trạm y tế dã chiến, tôi cùng đội công binh của quân đội tổ chức một điểm nấu cháo nóng miễn phí ngay tại sảnh tầng một của tòa nhà. Những nồi cháo thịt bò bốc khói nghi ngút, thơm phức mùi hành lá và tiêu đen được chia phát tận tay cho từng người già, phụ nữ và trẻ em đang run rẩy vì đói rét. Những nụ cười rạng rỡ và những giọt nước mắt biết ơn của bà con lối xóm đã làm tan chảy bầu không khí ảm đạm, lạnh lẽo suốt nửa tháng qua.\n\nChính quyền thành phố đã cử đại diện đến trao tặng tôi quyết định khen thưởng đột xuất vì nghĩa cử cao đẹp và tinh thần tương thân tương ái tuyệt vời trong thảm họa. Đứng giữa sảnh chung cư ấm áp tình người, tôi nhìn ra bầu trời mùa đông trong xanh vời vợi. Sau cơn mưa trời lại sáng, sau bão tuyết khắc nghiệt mầm sống sẽ lại vươn lên mạnh mẽ. Tôi tự hào vì mình đã sống một cuộc đời trọn vẹn, kiên cường bảo vệ sinh mệnh và lan tỏa hơi ấm yêu thương đến mọi người!"
